// app/dashboard/filter-bar.tsx
'use client';

import { usePathname, useRouter, useSearchParams } from 'next/navigation';
import { startTransition } from 'react';

export function FilterBar({ currentTimeframe, currentSide }: { currentTimeframe: string; currentSide: string }) {
  const router = useRouter();
  const pathname = usePathname();
  const searchParams = useSearchParams();

  function updateParam(key: string, value: string) {
    const next = new URLSearchParams(searchParams);
    next.set(key, value);
    startTransition(() => {
      router.replace(`${pathname}?${next.toString()}`);
    });
  }

  return (
    <div className="flex gap-3 rounded-2xl border bg-white/70 p-4 shadow-sm backdrop-blur">
      <select value={currentTimeframe} onChange={(e) => updateParam('timeframe', e.target.value)}>
        <option value="5m">5m</option>
        <option value="1h">1h</option>
        <option value="4h">4h</option>
      </select>
      <select value={currentSide} onChange={(e) => updateParam('side', e.target.value)}>
        <option value="all">All</option>
        <option value="long">Long</option>
        <option value="flat">Flat</option>
      </select>
    </div>
  );
}
```

Tradeoffs:
- You have to think harder about the server/client boundary.
- Some older React habits do not map cleanly to RSC, so there is a learning curve.

Why this choice:
- It keeps client JavaScript lean.
- It preserves a fast initial load.
- It is a practical modern Next.js setup that feels good without becoming framework fan fiction.

This is one of those places where the modern stack is honestly pretty nice. Server actions cut down a lot of glue code if you keep validation and writes on the server, then do a tiny optimistic update on the client.

Visible reasoning:
1. Settings forms are small, so server actions are a good fit.
2. Validation belongs near the mutation.
3. Optimistic UI matters because settings changes should feel instant.
4. Tailwind is perfect here if we keep the component small and readable.

Step-by-step solution outline:
1. Define a server action that validates `FormData`.
2. Persist the update.
3. Revalidate the route.
4. Use `useActionState` plus `useOptimistic` on the client.

Code:
