// app/settings/actions.ts
'use server';

import { z } from 'zod';
import { revalidatePath } from 'next/cache';

const SettingsSchema = z.object({
  defaultTimeframe: z.enum(['5m', '15m', '1h', '4h']),
  darkCharts: z.boolean(),
});

export async function saveSettings(_: unknown, formData: FormData) {
  const parsed = SettingsSchema.safeParse({
    defaultTimeframe: formData.get('defaultTimeframe'),
    darkCharts: formData.get('darkCharts') === 'on',
  });

  if (!parsed.success) {
    return { ok: false as const, errors: parsed.error.flatten().fieldErrors };
  }

  await db.userSettings.upsert({
    where: { userId: 'current-user' },
    update: parsed.data,
    create: { userId: 'current-user', ...parsed.data },
  });

  revalidatePath('/settings');
  return { ok: true as const };
}
```

