// app/settings/settings-form.tsx
'use client';

import { useActionState, useOptimistic } from 'react';
import { saveSettings } from './actions';

export function SettingsForm({ initial }: { initial: { defaultTimeframe: string; darkCharts: boolean } }) {
  const [optimistic, setOptimistic] = useOptimistic(initial);
  const [state, action, pending] = useActionState(saveSettings, { ok: true as const });

  return (
