# backend/app.py
from fastapi import FastAPI
from pydantic import BaseModel, Field
from typing import Literal

app = FastAPI()

class Position(BaseModel):
    symbol: str
    qty: float
    avg_price: float = Field(alias='avgPrice')
    side: Literal['long', 'flat']

class PortfolioSnapshot(BaseModel):
    equity: float
    cash: float
    positions: list[Position]

@app.get('/api/portfolio', response_model=PortfolioSnapshot)
def get_portfolio() -> PortfolioSnapshot:
    return PortfolioSnapshot(
        equity=12540.55,
        cash=2100.10,
        positions=[Position(symbol='BTCUSD', qty=0.15, avgPrice=61250.0, side='long')],
    )
