import time
from contextlib import contextmanager

@contextmanager
def traced_step(name: str, **meta: object):
    started = time.perf_counter()
    try:
        print(f'[trace:start] {name} meta={meta}')
        yield
    finally:
        elapsed_ms = (time.perf_counter() - started) * 1000
        print(f'[trace:end] {name} elapsed_ms={elapsed_ms:.1f} meta={meta}')

